def inline(s):
    s = html.escape(s)
    # autolink <https://...>
    s = re.sub(r'&lt;(https?://[^&]+?)&gt;', r'<a href="\1">\1</a>', s)
    # [text](url)
    s = re.sub(r'\[([^\]]+)\]\((https?://[^)]+)\)', r'<a href="\2">\1</a>', s)
    # bold
    s = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', s)
    return s

